	err   error
	calls int
}

func (s *stubBootstrapCredentialRepo) GetByUserID(ctx context.Context, userID uuid.UUID) (*data.UserCredential, error) {
	s.calls++
	if s.err != nil {
		return nil, s.err
	}
	if s.cred == nil || s.cred.UserID != userID {
		return nil, nil
	}
	return s.cred, nil
}

type stubBootstrapMembershipRepo struct {
	err        error
	calls      int
	lastUserID uuid.UUID
	lastRole   string
}

func (s *stubBootstrapMembershipRepo) SetRoleForUser(ctx context.Context, userID uuid.UUID, role string) error {
	s.calls++
	s.lastUserID = userID
	s.lastRole = role
	return s.err
}

type stubBootstrapSettingsRepo struct {
	values   map[string]*data.PlatformSetting
	getErr   error
	setErr   error
	setCalls int
}

func (s *stubBootstrapSettingsRepo) Get(ctx context.Context, key string) (*data.PlatformSetting, error) {
	if s.getErr != nil {
		return nil, s.getErr
	}
	if s.values == nil {
		return nil, nil
	}
	setting, ok := s.values[key]
	if !ok {
		return nil, nil
	}
	cp := *setting
	return &cp, nil
}

func (s *stubBootstrapSettingsRepo) Set(ctx context.Context, key, value string) (*data.PlatformSetting, error) {
	s.setCalls++
	if s.setErr != nil {
		return nil, s.setErr
	}
	if s.values == nil {
		s.values = make(map[string]*data.PlatformSetting)
	}
	setting := &data.PlatformSetting{Key: key, Value: value}
	s.values[key] = setting
	return setting, nil
}

func TestBootstrapPlatformAdminOnce(t *testing.T) {
	t.Parallel()

	logger := slog.New(slog.NewJSONHandler(io.Discard, nil))

	t.Run("首次执行成功并写入标记", func(t *testing.T) {
		userID := uuid.New()
		credRepo := &stubBootstrapCredentialRepo{
			cred: &data.UserCredential{UserID: userID, Login: "alice"},
		}
		membershipRepo := &stubBootstrapMembershipRepo{}
		settingsRepo := &stubBootstrapSettingsRepo{}

		err := bootstrapPlatformAdminOnce(context.Background(), credRepo, membershipRepo, settingsRepo, userID, logger)
		if err != nil {
			t.Fatalf("expected nil error, got %v", err)
		}
		if membershipRepo.calls != 1 {
			t.Fatalf("expected membership updates=1, got %d", membershipRepo.calls)
		}
		if membershipRepo.lastUserID != userID {
			t.Fatalf("expected user_id=%s, got %s", userID, membershipRepo.lastUserID)
		}
		if membershipRepo.lastRole != auth.RolePlatformAdmin {
			t.Fatalf("expected role=%q, got %q", auth.RolePlatformAdmin, membershipRepo.lastRole)
		}
		if settingsRepo.setCalls != 1 {
			t.Fatalf("expected marker writes=1, got %d", settingsRepo.setCalls)
		}
		if settingsRepo.values[bootstrapPlatformAdminSettingKey] == nil || settingsRepo.values[bootstrapPlatformAdminSettingKey].Value != userID.String() {
			t.Fatalf("expected marker value=%s, got %#v", userID, settingsRepo.values[bootstrapPlatformAdminSettingKey])
		}
	})

	t.Run("重复启动同 user_id 时幂等跳过", func(t *testing.T) {
		userID := uuid.New()
		credRepo := &stubBootstrapCredentialRepo{
			cred: &data.UserCredential{UserID: userID, Login: "alice"},
		}
		membershipRepo := &stubBootstrapMembershipRepo{}
		settingsRepo := &stubBootstrapSettingsRepo{
			values: map[string]*data.PlatformSetting{
				bootstrapPlatformAdminSettingKey: {Key: bootstrapPlatformAdminSettingKey, Value: userID.String()},
			},
		}

		err := bootstrapPlatformAdminOnce(context.Background(), credRepo, membershipRepo, settingsRepo, userID, logger)
		if err != nil {
			t.Fatalf("expected nil error, got %v", err)
		}
		if membershipRepo.calls != 0 {
			t.Fatalf("expected membership updates=0, got %d", membershipRepo.calls)
		}
		if settingsRepo.setCalls != 0 {
			t.Fatalf("expected marker writes=0, got %d", settingsRepo.setCalls)
		}
	})

	t.Run("标记存在但 user_id 不同则拒绝", func(t *testing.T) {
		userID := uuid.New()
		other := uuid.New()
		credRepo := &stubBootstrapCredentialRepo{
			cred: &data.UserCredential{UserID: userID, Login: "alice"},
		}
		membershipRepo := &stubBootstrapMembershipRepo{}
		settingsRepo := &stubBootstrapSettingsRepo{
			values: map[string]*data.PlatformSetting{
				bootstrapPlatformAdminSettingKey: {Key: bootstrapPlatformAdminSettingKey, Value: other.String()},
			},
		}

		err := bootstrapPlatformAdminOnce(context.Background(), credRepo, membershipRepo, settingsRepo, userID, logger)
		if err == nil {
			t.Fatalf("expected error, got nil")
		}
		if membershipRepo.calls != 0 {
			t.Fatalf("expected membership updates=0, got %d", membershipRepo.calls)
		}
		if settingsRepo.setCalls != 0 {
			t.Fatalf("expected marker writes=0, got %d", settingsRepo.setCalls)
		}
	})

	t.Run("用户不存在则失败且不写标记", func(t *testing.T) {
		userID := uuid.New()
		credRepo := &stubBootstrapCredentialRepo{}
		membershipRepo := &stubBootstrapMembershipRepo{}
		settingsRepo := &stubBootstrapSettingsRepo{}

		err := bootstrapPlatformAdminOnce(context.Background(), credRepo, membershipRepo, settingsRepo, userID, logger)
		if err == nil {
			t.Fatalf("expected error, got nil")
		}
		if membershipRepo.calls != 0 {
			t.Fatalf("expected membership updates=0, got %d", membershipRepo.calls)
		}
		if settingsRepo.setCalls != 0 {
			t.Fatalf("expected marker writes=0, got %d", settingsRepo.setCalls)
		}
	})
}

package auth

import (
	"strings"
	"testing"
)

func TestNewBcryptPasswordHasher(t *testing.T) {
	cases := []struct {
		name    string
		rounds  int
		wantErr bool
	}{
		{"zero_defaults_to_12", 0, false},
		{"min_valid", 4, false},
		{"mid_valid", 10, false},
		{"max_valid", 31, false},
		{"below_min", 3, true},
		{"above_max", 32, true},
		{"negative", -1, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h, err := NewBcryptPasswordHasher(tc.rounds)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("expected error, got nil")
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if h == nil {
				t.Fatalf("hasher must not be nil")
			}
		})
	}
}

func TestNewBcryptPasswordHasherDefaultRounds(t *testing.T) {
	h, err := NewBcryptPasswordHasher(0)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if h.rounds != defaultBcryptRounds {
		t.Errorf("rounds: got %d, want %d", h.rounds, defaultBcryptRounds)
	}
}

func TestHashPasswordAndVerifyRoundTrip(t *testing.T) {
	h := mustHasher(t)
	password := "correct-horse-battery-staple"

	hashed, err := h.HashPassword(password)
	if err != nil {
		t.Fatalf("hash: %v", err)
	}
	if hashed == "" {
		t.Fatalf("hash must not be empty")
	}
	if hashed == password {
		t.Fatalf("hash must differ from plaintext")
	}

	if !h.VerifyPassword(password, hashed) {
		t.Errorf("VerifyPassword should return true for correct password")
	}
	if h.VerifyPassword("wrong-password", hashed) {
		t.Errorf("VerifyPassword should return false for wrong password")
	}
}

func TestHashPasswordSaltRandomness(t *testing.T) {
	h := mustHasher(t)
	password := "same-password"

	h1, err := h.HashPassword(password)
	if err != nil {
		t.Fatalf("first hash: %v", err)
	}
	h2, err := h.HashPassword(password)
	if err != nil {
		t.Fatalf("second hash: %v", err)
	}
	if h1 == h2 {
		t.Fatalf("two hashes of same password must differ (random salt), both got %q", h1)
	}
	if !h.VerifyPassword(password, h1) {
		t.Errorf("first hash should verify")
	}
	if !h.VerifyPassword(password, h2) {
		t.Errorf("second hash should verify")
	}
}

func TestVerifyPasswordEmptyHash(t *testing.T) {
	h := mustHasher(t)

	if h.VerifyPassword("anything", "") {
		t.Errorf("empty hash must return false")
	}
	if h.VerifyPassword("anything", "   ") {
		t.Errorf("whitespace-only hash must return false")
	}
	if h.VerifyPassword("anything", "\t\n") {
		t.Errorf("tab/newline hash must return false")
	}
}

func TestVerifyPasswordInvalidHash(t *testing.T) {
	h := mustHasher(t)

	if h.VerifyPassword("password", "not-a-bcrypt-hash") {
		t.Errorf("garbage hash must return false")
	}
	if h.VerifyPassword("password", "$2a$10$invalid") {
		t.Errorf("truncated bcrypt hash must return false")
	}
}

func TestHashAndVerifyEmptyPassword(t *testing.T) {
	h := mustHasher(t)

	hashed, err := h.HashPassword("")
	if err != nil {
		t.Fatalf("hash empty password: %v", err)
	}
	if !h.VerifyPassword("", hashed) {
		t.Errorf("empty password should verify against its own hash")
	}
	if h.VerifyPassword("non-empty", hashed) {
		t.Errorf("non-empty password should not verify against empty password hash")
	}
}

func TestHashPasswordBcrypt72ByteLimit(t *testing.T) {
	h := mustHasher(t)

	// golang.org/x/crypto/bcrypt rejects passwords > 72 bytes
	long := strings.Repeat("a", 73)
	_, err := h.HashPassword(long)
	if err == nil {
		t.Fatalf("expected error for >72 byte password")
	}

	exact := strings.Repeat("a", 72)
	hashed, err := h.HashPassword(exact)
	if err != nil {
		t.Fatalf("hash 72-byte password: %v", err)
	}
	if !h.VerifyPassword(exact, hashed) {
		t.Errorf("72-byte password should verify")
	}
}

func TestBcryptRoundsInHashOutput(t *testing.T) {
	h4, err := NewBcryptPasswordHasher(4)
	if err != nil {
		t.Fatalf("new hasher rounds=4: %v", err)
	}
	h5, err := NewBcryptPasswordHasher(5)
	if err != nil {
		t.Fatalf("new hasher rounds=5: %v", err)
	}

	password := "test-password"
	hash4, err := h4.HashPassword(password)
	if err != nil {
		t.Fatalf("hash rounds=4: %v", err)
	}
	hash5, err := h5.HashPassword(password)
	if err != nil {
		t.Fatalf("hash rounds=5: %v", err)
	}

	if !strings.Contains(hash4, "$04$") {
		t.Errorf("rounds=4 hash should contain $04$, got %q", hash4)
	}
	if !strings.Contains(hash5, "$05$") {
		t.Errorf("rounds=5 hash should contain $05$, got %q", hash5)
	}

	if !h4.VerifyPassword(password, hash5) {
		t.Errorf("rounds=4 hasher should verify rounds=5 hash")
	}
	if !h5.VerifyPassword(password, hash4) {
		t.Errorf("rounds=5 hasher should verify rounds=4 hash")
	}
}

func mustHasher(t *testing.T) *BcryptPasswordHasher {
	t.Helper()
	h, err := NewBcryptPasswordHasher(4)
	if err != nil {
		t.Fatalf("create hasher: %v", err)
	}
	return h
}

package auth

import (
	"errors"
	"strings"
	"testing"
)

func TestValidateRegistrationPassword(t *testing.T) {
	cases := []struct {
		name    string
		value   string
		wantErr bool
	}{
		{name: "too_short", value: "abc123", wantErr: true},
		{name: "letters_only", value: "abcdefgh", wantErr: true},
		{name: "digits_only", value: "12345678", wantErr: true},
		{name: "too_long", value: strings.Repeat("a", 72) + "1", wantErr: true},
		{name: "valid_ascii", value: "abc12345", wantErr: false},
		{name: "valid_unicode", value: "密码123456", wantErr: false},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			err := ValidateRegistrationPassword(tc.value)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("expected error, got nil")
				}
				var policyErr PasswordPolicyError
				if !errors.As(err, &policyErr) {
					t.Fatalf("expected PasswordPolicyError, got %T", err)
				}
				if err.Error() != passwordPolicyMessage {
					t.Fatalf("message = %q, want %q", err.Error(), passwordPolicyMessage)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
		})
	}
}

package auth

import (
	"context"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"fmt"
	"log/slog"
	"strings"
	"time"

	"arkloop/services/api/internal/data"

	"github.com/google/uuid"
)

const emailOTPTokenTTL = 10 * time.Minute

// OTPExpiredOrUsedError 表示登录 OTP 无效、已用或已过期。
type OTPExpiredOrUsedError struct{}

func (OTPExpiredOrUsedError) Error() string {
	return "otp invalid or expired"
}

// EmailOTPLoginService 处理邮箱 OTP 无密码登录。
type EmailOTPLoginService struct {
	userRepo         *data.UserRepository
	otpRepo          *data.EmailOTPTokenRepository
	jobRepo          *data.JobRepository
	tokenService     *JwtAccessTokenService
	refreshTokenRepo *data.RefreshTokenRepository
	membershipRepo   *data.AccountMembershipRepository
	riskControl      EmailOTPRiskControl
	settingsRepo     *data.PlatformSettingsRepository
	envBaseURL       string
	projectRepo      *data.ProjectRepository
}

func NewEmailOTPLoginService(
	userRepo *data.UserRepository,
	otpRepo *data.EmailOTPTokenRepository,
	jobRepo *data.JobRepository,
	tokenService *JwtAccessTokenService,
	refreshTokenRepo *data.RefreshTokenRepository,
	membershipRepo *data.AccountMembershipRepository,
	riskControl EmailOTPRiskControl,
	projectRepo *data.ProjectRepository,
) (*EmailOTPLoginService, error) {
	if userRepo == nil {
		return nil, errors.New("userRepo must not be nil")
	}
	if otpRepo == nil {
		return nil, errors.New("otpRepo must not be nil")
	}
	if jobRepo == nil {
		return nil, errors.New("jobRepo must not be nil")
	}
	if tokenService == nil {
		return nil, errors.New("tokenService must not be nil")
	}
	if refreshTokenRepo == nil {
		return nil, errors.New("refreshTokenRepo must not be nil")
	}
	if membershipRepo == nil {
		return nil, errors.New("membershipRepo must not be nil")
	}
	return &EmailOTPLoginService{
		userRepo:         userRepo,
		otpRepo:          otpRepo,
		jobRepo:          jobRepo,
		tokenService:     tokenService,
		refreshTokenRepo: refreshTokenRepo,
		membershipRepo:   membershipRepo,
		riskControl:      riskControl,
		projectRepo:      projectRepo,
	}, nil
}

func (s *EmailOTPLoginService) SetAppBaseURL(envBaseURL string, repo *data.PlatformSettingsRepository) {
	s.envBaseURL = strings.TrimSpace(envBaseURL)
	s.settingsRepo = repo
}

func (s *EmailOTPLoginService) RefreshTokenTTLSeconds() int {
	if s == nil || s.tokenService == nil {
		return 0
	}
	return s.tokenService.RefreshTokenTTLSeconds()
}

// SendLoginOTP 向指定邮箱发送登录 OTP。
// 若邮箱不存在则静默返回 nil（不暴露用户是否存在）。
func (s *EmailOTPLoginService) SendLoginOTP(ctx context.Context, email string) error {
	if s.riskControl != nil {
		if err := s.riskControl.AllowSend(ctx, email); err != nil {
			return formatOTPProtectionError(err)
		}
	}

	user, err := s.userRepo.GetByEmail(ctx, email)
	if err != nil {
		return fmt.Errorf("lookup user: %w", err)
	}
	if user == nil || user.Status != "active" {
		return nil
	}

	plaintext, tokenHash, err := generateEmailOTPToken()
	if err != nil {
		return fmt.Errorf("generate otp: %w", err)
	}

	expiresAt := time.Now().UTC().Add(emailOTPTokenTTL)
	if _, err := s.otpRepo.Create(ctx, user.ID, tokenHash, expiresAt); err != nil {
		return fmt.Errorf("create otp token: %w", err)
	}

	locale := ""
	if user.Locale != nil {
		locale = *user.Locale
	}

	username := user.Username

	var subject, htmlBody, text string
	if locale == "zh" {
		subject = "登录验证码"
		htmlBody = buildEmailHTMLZh(emailParams{
			Title:    "登录验证码",
			Greeting: fmt.Sprintf("你好 %s，", username),
			Code:     plaintext,
			Notice:   "验证码有效期 10 分钟，请勿泄露",
		})
		text = fmt.Sprintf("你好 %s，\n\n登录验证码：%s\n\n有效期 10 分钟，请勿泄露。", username, plaintext)
	} else {
		subject = "Your login code"
		htmlBody = buildEmailHTML(emailParams{
			Title:    "Your login code",
			Greeting: fmt.Sprintf("Hi %s,", username),
			Code:     plaintext,
			Notice:   "Expires in 10 minutes · Do not share this code",
		})
		text = fmt.Sprintf("Hi %s,\n\nYour login code: %s\n\nExpires in 10 minutes. Do not share this code.", username, plaintext)
	}

	if _, err := s.jobRepo.EnqueueEmail(ctx, email, subject, htmlBody, text); err != nil {
		return fmt.Errorf("enqueue login otp email: %w", err)
	}
	return nil
}

// VerifyLoginOTP 验证 OTP 并签发 token 对。
// 若验证成功且邮箱未验证，同时标记邮箱已验证。
func (s *EmailOTPLoginService) VerifyLoginOTP(ctx context.Context, email string, code string) (IssuedTokenPair, error) {
	if code == "" {
		return IssuedTokenPair{}, OTPExpiredOrUsedError{}
	}
	if s.riskControl != nil {
		if err := s.riskControl.EnsureVerifyAllowed(ctx, email); err != nil {
			return IssuedTokenPair{}, formatOTPProtectionError(err)
		}
	}

	user, err := s.userRepo.GetByEmail(ctx, email)
	if err != nil {
		return IssuedTokenPair{}, fmt.Errorf("lookup user: %w", err)
	}
	if user == nil {
		if s.riskControl != nil {
			if err := s.riskControl.RecordVerifyFailure(ctx, email); err != nil {
				return IssuedTokenPair{}, formatOTPProtectionError(err)
			}
		}
		return IssuedTokenPair{}, OTPExpiredOrUsedError{}
	}
	if user.Status != "active" {
		return IssuedTokenPair{}, SuspendedUserError{UserID: user.ID, Status: user.Status}
	}

	tokenHash := hashVerifyToken(code)
	userID, ok, err := s.otpRepo.Consume(ctx, tokenHash)
	if err != nil {
		return IssuedTokenPair{}, err
	}
	if !ok || userID != user.ID {
		if s.riskControl != nil {
			if err := s.riskControl.RecordVerifyFailure(ctx, email); err != nil {
				return IssuedTokenPair{}, formatOTPProtectionError(err)
			}
		}
		return IssuedTokenPair{}, OTPExpiredOrUsedError{}
	}

	if user.EmailVerifiedAt == nil {
		if err := s.userRepo.SetEmailVerified(ctx, user.ID); err != nil {
			return IssuedTokenPair{}, fmt.Errorf("set email verified: %w", err)
		}
	}

	pair, err := s.issueTokenPair(ctx, user.ID)
	if err != nil {
		return IssuedTokenPair{}, err
	}
	if s.riskControl != nil {
		_ = s.riskControl.ResetVerifyState(ctx, email)
	}
	return pair, nil
}

func generateEmailOTPToken() (plaintext, hash string, err error) {
	var b [4]byte
	if _, err = rand.Read(b[:]); err != nil {
		return "", "", err
	}
	n := binary.BigEndian.Uint32(b[:])%90000000 + 10000000
	plaintext = fmt.Sprintf("%08d", n)
	hash = hashVerifyToken(plaintext)
	return plaintext, hash, nil
}

func (s *EmailOTPLoginService) issueTokenPair(ctx context.Context, userID uuid.UUID) (IssuedTokenPair, error) {
	now := time.Now().UTC()

	var accountID uuid.UUID
	var accountRole string
	if membership, err := s.membershipRepo.GetDefaultForUser(ctx, userID); err == nil && membership != nil {
		accountID = membership.AccountID
		accountRole = membership.Role
	}

	if accountID != uuid.Nil && s.projectRepo != nil {
		if _, err := s.projectRepo.GetOrCreateDefaultByOwner(ctx, accountID, userID); err != nil {
			slog.WarnContext(ctx, "auth: failed to self-heal default project", "error", err)
		}
	}

	accessToken, err := s.tokenService.Issue(userID, accountID, accountRole, now)
	if err != nil {
		return IssuedTokenPair{}, err
	}

	plaintext, hash, expiresAt, err := s.tokenService.IssueRefreshToken(now)
	if err != nil {
		return IssuedTokenPair{}, err
	}

	if _, err = s.refreshTokenRepo.Create(ctx, userID, hash, expiresAt); err != nil {
		return IssuedTokenPair{}, err
	}

	return IssuedTokenPair{
		AccessToken:  accessToken,
		RefreshToken: plaintext,
		UserID:       userID,
	}, nil
}

package auth

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"fmt"
	"strings"
	"time"

	"arkloop/services/api/internal/data"

	"github.com/google/uuid"
)

const emailVerifyTokenTTL = 1 * time.Hour

type TokenAlreadyUsedOrExpiredError struct{}

func (TokenAlreadyUsedOrExpiredError) Error() string {
	return "verification token invalid or expired"
}

const settingAppBaseURL = "app.base_url"

// EmailVerifyService 管理邮箱验证 token 的生成与消耗。
type EmailVerifyService struct {
	tokenRepo    *data.EmailVerificationTokenRepository
	userRepo     *data.UserRepository
	jobRepo      *data.JobRepository
	envBaseURL   string
	settingsRepo *data.PlatformSettingsRepository
}

func NewEmailVerifyService(
	tokenRepo *data.EmailVerificationTokenRepository,
	userRepo *data.UserRepository,
	jobRepo *data.JobRepository,
) (*EmailVerifyService, error) {
	if tokenRepo == nil {
		return nil, errors.New("tokenRepo must not be nil")
	}
	if userRepo == nil {
		return nil, errors.New("userRepo must not be nil")
	}
	if jobRepo == nil {
		return nil, errors.New("jobRepo must not be nil")
	}
	return &EmailVerifyService{
		tokenRepo: tokenRepo,
		userRepo:  userRepo,
		jobRepo:   jobRepo,
	}, nil
}

// SetAppBaseURL 设置 AppBaseURL 的 env 兜底值和 DB 配置源（DB 优先）。
func (s *EmailVerifyService) SetAppBaseURL(envBaseURL string, repo *data.PlatformSettingsRepository) {
	s.envBaseURL = strings.TrimSpace(envBaseURL)
	s.settingsRepo = repo
}

// resolveBaseURL 发送时动态读取：DB 中 app.base_url 优先，env 兜底。
func (s *EmailVerifyService) resolveBaseURL(ctx context.Context) string {
	if s.settingsRepo != nil {
		if setting, err := s.settingsRepo.Get(ctx, settingAppBaseURL); err == nil && setting != nil {
			if v := strings.TrimSpace(setting.Value); v != "" {
				return strings.TrimRight(v, "/")
			}
		}
	}
	return strings.TrimRight(s.envBaseURL, "/")
}

// SendVerification 为用户生成验证 token 并入队发送邮件。
// 若用户没有邮箱则返回错误。
func (s *EmailVerifyService) SendVerification(ctx context.Context, userID uuid.UUID, username string) error {
	user, err := s.userRepo.GetByID(ctx, userID)
	if err != nil {
		return err
	}
	if user == nil {
		return fmt.Errorf("user not found")
	}
	if user.Email == nil || *user.Email == "" {
		return fmt.Errorf("user has no email address")
	}

	plaintext, tokenHash, err := generateVerifyToken()
	if err != nil {
		return fmt.Errorf("generate token: %w", err)
	}

	expiresAt := time.Now().UTC().Add(emailVerifyTokenTTL)
	if _, err := s.tokenRepo.Create(ctx, userID, tokenHash, expiresAt); err != nil {
		return fmt.Errorf("create verification token: %w", err)
	}

	baseURL := s.resolveBaseURL(ctx)

	locale := ""
	if user.Locale != nil {
		locale = *user.Locale
	}

	var subject, htmlBody, text string

	if locale == "zh" {
		subject = "验证您的邮箱"
		params := emailParams{
			Title:    "验证您的邮箱",
			Greeting: fmt.Sprintf("你好 %s，", username),
			Code:     plaintext,
			Notice:   "验证码有效期 1 小时，请勿泄露",
		}
		if baseURL != "" {
			link := baseURL + "/verify?token=" + plaintext
			params.LinkURL = link
			params.LinkLabel = "立即验证邮箱"
			text = fmt.Sprintf("你好 %s，\n\n邮箱验证码：%s\n\n或点击链接验证：\n%s\n\n有效期 1 小时。", username, plaintext, link)
		} else {
			text = fmt.Sprintf("你好 %s，\n\n邮箱验证码：%s\n\n有效期 1 小时。", username, plaintext)
		}
		htmlBody = buildEmailHTMLZh(params)
	} else {
		subject = "Verify your email address"
		params := emailParams{
			Title:    "Verify your email",
			Greeting: fmt.Sprintf("Hi %s,", username),
			Code:     plaintext,
			Notice:   "Expires in 1 hour · Do not share this code",
		}
		if baseURL != "" {
			link := baseURL + "/verify?token=" + plaintext
			params.LinkURL = link
			params.LinkLabel = "Verify email"
			text = fmt.Sprintf("Hi %s,\n\nYour email verification code: %s\n\nOr verify automatically:\n%s\n\nExpires in 1 hour.", username, plaintext, link)
		} else {
			text = fmt.Sprintf("Hi %s,\n\nYour email verification code: %s\n\nExpires in 1 hour.", username, plaintext)
		}
		htmlBody = buildEmailHTML(params)
	}

	if _, err := s.jobRepo.EnqueueEmail(ctx, *user.Email, subject, htmlBody, text); err != nil {
		return fmt.Errorf("enqueue verification email: %w", err)
	}
	return nil
}

// ConfirmVerification 消耗 token 并将用户邮箱标记为已验证。
func (s *EmailVerifyService) ConfirmVerification(ctx context.Context, plaintext string) error {
	if plaintext == "" {
		return TokenAlreadyUsedOrExpiredError{}
	}

	tokenHash := hashVerifyToken(plaintext)
	userID, ok, err := s.tokenRepo.Consume(ctx, tokenHash)
	if err != nil {
		return err
	}
	if !ok {
		return TokenAlreadyUsedOrExpiredError{}
	}

	return s.userRepo.SetEmailVerified(ctx, userID)
}

func generateVerifyToken() (plaintext, hash string, err error) {
	var b [4]byte
	if _, err = rand.Read(b[:]); err != nil {
		return
	}
	// 100000–999999：均匀分布的6位数字
	n := binary.BigEndian.Uint32(b[:])%900000 + 100000
	plaintext = fmt.Sprintf("%06d", n)
	hash = hashVerifyToken(plaintext)
	return
}

func hashVerifyToken(plaintext string) string {
	sum := sha256.Sum256([]byte(plaintext))
	return hex.EncodeToString(sum[:])
}

package auth

import (
	"fmt"
	"html"
	"strings"
)

// emailParams 控制邮件 HTML 的渲染内容。
type emailParams struct {
	Title     string // 卡片标题
	Greeting  string // 问候语，如 "Hi Alice,"
	BodyLines []string // 标题下方正文段落
	Code      string // 6 位验证码
	Notice    string // 验证码下方的小提示
	LinkURL   string // 可选 CTA 链接
	LinkLabel string // CTA 按钮文字
}

// buildEmailHTML 返回完整的 HTML 邮件字符串。
// 采用 light 主题（兼容所有主流邮件客户端），
// 风格与前端 light mode 保持一致。
func buildEmailHTML(p emailParams) string {
	var b strings.Builder

	// 颜色常量，与前端 light theme CSS 变量对应
	const (
		colorPageBg    = "#F5F5F4"
		colorCardBg    = "#FFFFFF"
		colorBorder    = "#E2E2E0"
		colorCodeBg    = "#F8F8F7"
		colorPrimary   = "#141412"
		colorSecondary = "#3D3D3B"
		colorMuted     = "#9C9A92"
		colorBtnBg     = "#1A1A18"
		colorBtnText   = "#FAFAFA"
		fontStack      = "-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif"
	)

	// -- head --
	b.WriteString(`<!DOCTYPE html><html lang="en"><head>`)
	b.WriteString(`<meta charset="UTF-8">`)
	b.WriteString(`<meta name="viewport" content="width=device-width,initial-scale=1.0">`)
	_, _ = fmt.Fprintf(&b, `<title>%s</title>`, html.EscapeString(p.Title))
	b.WriteString(`</head>`)

	// -- body --
	_, _ = fmt.Fprintf(&b,
		`<body style="margin:0;padding:0;background:%s;font-family:%s;-webkit-font-smoothing:antialiased;">`,
		colorPageBg, fontStack,
	)

	// 外层居中容器
	_, _ = fmt.Fprintf(&b,
		`<table width="100%%" cellpadding="0" cellspacing="0" role="presentation" style="background:%s;">`,
		colorPageBg,
	)
	b.WriteString(`<tr><td align="center" style="padding:52px 20px 40px;">`)

	// 品牌 wordmark
	_, _ = fmt.Fprintf(&b,
		`<p style="margin:0 0 28px;font-size:15px;font-weight:600;letter-spacing:-0.2px;color:%s;">Arkloop</p>`,
		colorPrimary,
	)

	// 卡片
	_, _ = fmt.Fprintf(&b,
		`<table width="100%%" cellpadding="0" cellspacing="0" role="presentation" `+
			`style="max-width:480px;background:%s;border:1px solid %s;border-radius:16px;`+
			`box-shadow:0 4px 24px rgba(0,0,0,0.07);">`,
		colorCardBg, colorBorder,
	)
	b.WriteString(`<tr><td style="padding:40px 40px 36px;">`)

	// 标题
	_, _ = fmt.Fprintf(&b,
		`<h1 style="margin:0 0 8px;font-size:20px;font-weight:600;letter-spacing:-0.3px;color:%s;">%s</h1>`,
		colorPrimary, html.EscapeString(p.Title),
	)

	// 问候语
	if p.Greeting != "" {
		_, _ = fmt.Fprintf(&b,
			`<p style="margin:0 0 24px;font-size:14px;line-height:1.65;color:%s;">%s</p>`,
			colorSecondary, html.EscapeString(p.Greeting),
		)
	}

	// 正文段落
	for _, line := range p.BodyLines {
		_, _ = fmt.Fprintf(&b,
			`<p style="margin:0 0 16px;font-size:14px;line-height:1.65;color:%s;">%s</p>`,
			colorSecondary, html.EscapeString(line),
		)
	}

	// 验证码区块
	if p.Code != "" {
		_, _ = fmt.Fprintf(&b,
			`<table width="100%%" cellpadding="0" cellspacing="0" role="presentation" `+
				`style="margin-bottom:16px;">`,
		)
		b.WriteString(`<tr><td align="center" style="` +
			fmt.Sprintf(`background:%s;border:1px solid %s;`, colorCodeBg, colorBorder) +
			`border-radius:12px;padding:28px 20px;">`)
		_, _ = fmt.Fprintf(&b,
			`<span style="font-size:36px;font-weight:700;letter-spacing:12px;color:%s;`+
				`font-variant-numeric:tabular-nums;display:inline-block;">%s</span>`,
			colorPrimary, html.EscapeString(p.Code),
		)
		b.WriteString(`</td></tr></table>`)
	}

	// 验证码下方提示
	if p.Notice != "" {
		_, _ = fmt.Fprintf(&b,
			`<p style="margin:0 0 28px;font-size:12px;color:%s;text-align:center;line-height:1.6;">%s</p>`,
			colorMuted, html.EscapeString(p.Notice),
		)
	}

	// CTA 按钮（可选）
	if p.LinkURL != "" && p.LinkLabel != "" {
		_, _ = fmt.Fprintf(&b,
			`<table width="100%%" cellpadding="0" cellspacing="0" role="presentation">`,
		)
		b.WriteString(`<tr><td align="center">`)
		_, _ = fmt.Fprintf(&b,
			`<a href="%s" target="_blank" style="`+
				`display:inline-block;padding:11px 28px;`+
				`background:%s;color:%s;`+
				`font-size:14px;font-weight:500;letter-spacing:-0.1px;`+
				`text-decoration:none;border-radius:10px;`+
				`font-family:%s;">%s</a>`,
			html.EscapeString(p.LinkURL), colorBtnBg, colorBtnText,
			fontStack, html.EscapeString(p.LinkLabel),
		)
		b.WriteString(`</td></tr></table>`)
	}

	// 卡片关闭
	b.WriteString(`</td></tr></table>`)

	// 分割线
	_, _ = fmt.Fprintf(&b,
		`<table width="100%%" cellpadding="0" cellspacing="0" role="presentation" style="max-width:480px;margin-top:0;">`,
	)
	b.WriteString(`<tr><td style="padding:0 40px;">`)
	_, _ = fmt.Fprintf(&b, `<hr style="border:none;border-top:1px solid %s;margin:0;">`, colorBorder)
	b.WriteString(`</td></tr></table>`)

	// 页脚
	_, _ = fmt.Fprintf(&b,
		`<p style="margin:20px 0 0;font-size:12px;color:%s;text-align:center;line-height:1.7;">`,
		colorMuted,
	)
	b.WriteString(`Arkloop &nbsp;·&nbsp; This email was sent automatically, please do not reply.</p>`)

	b.WriteString(`</td></tr></table>`)
	b.WriteString(`</body></html>`)

	return b.String()
}

// buildEmailHTMLZh 中文版本，内容由外部传入，结构与 buildEmailHTML 一致。
func buildEmailHTMLZh(p emailParams) string {
	// 结构完全相同，只改页脚文字
	original := buildEmailHTML(p)
	return strings.ReplaceAll(
		original,
		"This email was sent automatically, please do not reply.",
		"此邮件由系统自动发送，请勿直接回复。",
	)
}

